function g({registerIndicator:A,sourceValues:k,nulls:X}){const h=(c,e)=>{const i=c.length,u=new Array(i).fill(NaN),f=new Array(e).fill(NaN),p=new Array(e).fill(NaN);let r=0,d=0,N=0,b=0,s=0,t=0,y=0;for(let n=0;n<i;n++){if(y>=e){const o=f[t],l=p[t];Number.isFinite(l)&&(r-=o,d-=l,N-=o*l,b-=o*o,s-=1)}const a=y,m=Number.isFinite(c[n])?c[n]:NaN;if(f[t]=a,p[t]=m,Number.isFinite(m)&&(r+=a,d+=m,N+=a*m,b+=a*a,s+=1),t=(t+1)%e,y+=1,s>=2){const o=s*b-r*r;if(o!==0){const l=(s*N-r*d)/o;Number.isFinite(l)&&(u[n]=l)}}}return u};A({id:"oa-accel",name:"Acceleration (Slope of Slope) (ACCEL)",category:"Numerics",placement:"pane",inputs:[{key:"period",type:"number",label:"Period",default:14,min:2,max:5e3,step:1,tooltip:"Lookback used for both regressions. Pine refuses a length of 1 or less."},{key:"source",type:"source",label:"Source",default:"close"}],plots:[{key:"accel",type:"line",title:"Accel",style:{color:"#ffeb3b",lineWidth:2}}],calc(c,e){const i=Math.max(2,Math.floor(Number(e.period)||14)),u=k(c,e.source??"close"),f=h(u,i),p=h(f,i);return{accel:X(p)}}})}export{g as default};
